// Apply coupon discount to subtotal in cents
function applyDiscount(subtotalCents, coupon) {
  const code = (coupon || "").trim().toUpperCase();
  if (code === "SAVE10") {
    return Math.round(subtotalCents * 0.10);
  }
  return 0;
}

// Helper to compute net base amount
function calculateNetBase(baseCents, discountCents) {
  return Math.max(0, baseCents - discountCents);
}

module.exports = { applyDiscount, calculateNetBase };

